; Xantera sound engine - 4x4 World Trophy (E) (M5) [C][!].gbc
;
; Generated by tools/gen_xan.py. Assembles byte-identical with RGBDS 1.0.0:
;   bank 0  $3343-$3918  waves, noise table, driver, SFX records
;   bank $3C $4000-$6D3B  two songs
;
; Hooks in the game (bank 0):
;   $01AF  call XSnd_Init                (boot)
;   $025F  call XSnd_Update              (VBlank)
;   $0262  call XSnd_SfxTimers           (VBlank)
;   $03D7  call XSnd_EngineUpdate        (timer interrupt)

INCLUDE "hardware.inc"
INCLUDE "xantera_sound.inc"

SECTION "Xantera sound (bank 0)", ROM0[$3343]

; 16-byte waves, selected by the $4n event (XWaveTable + n*16).
; Only waves 0 (song start) and 2 (songs, engine) are used. n > 5
; would read on into XNoiseTable and beyond.
XWaveTable:
XWave0:  ; default (loaded at init and song start)
    db $76, $43, $21, $00, $00, $01, $23, $46, $89, $BC, $DE, $FF, $FF, $FE, $DC, $B9
XWave1:  ; unused
    db $88, $99, $98, $75, $32, $10, $12, $35, $8A, $CD, $EF, $ED, $CA, $87, $66, $67
XWave_Engine:
XWave2:  ; songs ($42) and the engine voice
    db $88, $89, $AA, $CF, $00, $35, $66, $77, $88, $89, $9A, $CF, $F0, $35, $56, $77
XWave3:  ; unused (ramp)
    db $88, $99, $AA, $BB, $CC, $DD, $EE, $FF, $00, $11, $22, $33, $44, $55, $66, $77
XWave4:  ; unused (square)
    db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $00, $00, $00, $00, $00, $00, $00, $00
XWave5:  ; unused (looks like random bytes)
    db $5B, $4E, $C1, $23, $A6, $FA, $3E, $0A, $3C, $BD, $78, $5B, $8B, $D3, $B2, $E4

; ch4 instruments: NR41, NR42 envelope bits (ORed with the note volume),
; NR43, NR44. Indexed by the low nibble of a $13 note (no bound check).
XNoiseTable:
    noise_inst $00, $01, $51, $C0   ; 0
    noise_inst $00, $02, $22, $C0   ; 1
    noise_inst $00, $02, $22, $C7   ; 2
    noise_inst $3D, $04, $00, $C0   ; 3
    noise_inst $36, $04, $00, $C0   ; 4
    noise_inst $31, $04, $01, $C0   ; 5
    noise_inst $37, $04, $5A, $C0   ; 6
    noise_inst $00, $04, $A0, $C0   ; 7
    noise_inst $00, $02, $20, $C0   ; 8
    noise_inst $00, $09, $20, $C0   ; 9

; Older SFX set: nothing points here (includes the only ch2 records).
XSfx1_33CB:
    sfx1 $00, $74, $80, $94, $39, $C7   ; unreferenced
XSfx1_33D1:
    sfx1 $06, $67, $E8, $F7, $7F, $C7   ; unreferenced
XSfx2_33D7:
    sfx2 $00, $87, $94, $89, $C6   ; unreferenced
XSfx2_33DC:
    sfx2 $10, $C0, $F7, $7F, $87   ; unreferenced
XSfx3_33E1:
    sfx3 $00, $80, $74, $20, $00, $C6   ; unreferenced
XSfx3_33E7:
    sfx3 $07, $80, $74, $20, $00, $C6   ; unreferenced
XSfx4_33ED:
    sfx4 $00, $00, $F7, $4F, $C0   ; unreferenced
XSfx4_33F2:
    sfx4 $07, $00, $F7, $4F, $C0   ; unreferenced
XSfx4_33F7:
    sfx4 $00, $00, $81, $A0, $C0   ; unreferenced

XSnd_Init::
    ld hl,rNR50                  ; NR50 = $77
    ld a,$77
    ld [hl+],a
    ld a,$FF                     ; NR51 = $FF
    ld [hl+],a
    ld a,$8F                     ; NR52 = $8F
    ld [hl],a
    ld hl,XWaveTable             ; wave 0
    call XSnd_LoadWave
    ld a,$20                     ; NR32 = 100%
    ldh [rNR32],a
    ld a,$00
    ld hl,wXSndFlags             ; clear flags and the four SFX timers
    ld [hl+],a
    ld [hl+],a
    ld [hl+],a
    ld [hl+],a
    ld [hl],a
    ret

XSnd_LoadWave:
    ld a,h                       ; remember the wave (big-endian)
    ld e,l
    push hl
    ld hl,wXWaveCur
    ld [hl+],a
    ld [hl],e
    pop hl
    ld a,$00                     ; DAC off while writing wave RAM
    ldh [rNR30],a
    ldh [rNR31],a
    ld de,rWAVE
    ld b,$00
.copy:
    ld a,[hl+]
    ld [de],a
    inc de
    inc b
    ld a,b
    cp $10
    jr nz,XSnd_LoadWave.copy
    ret

XSnd_PlaySong::
    ld [wXMusBank],a             ; a = bank, de = song
    ld a,[wXSndFlags]            ; b = SFX bits | $80 ...
    or $80
    and $8F
    ld b,a
    ldh a,[rNR52]                ; ... ANDed into NR52: only bit 7 is writable, so no effect
    and b
    ldh [rNR52],a
    ld hl,wXMusPtr
    ld a,d
    ld [hl+],a
    ld [hl],e
    ld a,$00
    ld hl,wXMusTime              ; clock = 0
    ld [hl+],a
    ld [hl],a
    inc a                        ; playing = 1
    ld [wXMusPlaying],a
    ld hl,XWaveTable
    ld a,[wXSndFlags]            ; ch3 owned by an SFX?
    bit 2,a
    jr z,XSnd_PlaySong.noSfx3
    ld a,h                       ; BUG: means wXWaveSave = XWaveTable, but stores
    ld [wXWaveSave],a
    ld l,a                       ; h twice: wXWaveSave = $3333
    ld [wXWaveSave+1],a
    ret
.noSfx3:
    call XSnd_LoadWave
    ret

XSnd_StopMusic::
    ld a,$00                     ; playing = 0
    ld [wXMusPlaying],a
    ld a,[wXSndFlags]            ; same no-op NR52 write as above
    or $80
    and $8F
    ld b,a
    ldh a,[rNR52]
    and b
    ldh [rNR52],a
    ld a,b                       ; ch1/ch2/ch4 are left sounding
    bit 2,a
    jr nz,XSnd_StopMusic.ret
    ld a,$00
    ldh [rNR30],a
.ret:
    ret

XSnd_QueueSong::
    ld hl,wXQueuedPtr            ; de = song, b = bank
    ld a,d
    ld [hl+],a
    ld a,e
    ld [hl+],a
    ld [hl],b
    ld a,[wXSndFlags]
    set 7,a
    ld [wXSndFlags],a
    ret

XSnd_Update::
    ld a,[wXMusPlaying]          ; called from VBlank
    and a
    jr nz,XSnd_Update.playing
    ret
.playing:
    ld a,[wXCurBank]             ; save the game bank, map the song bank
    ld [wXSavedBank],a
    ld a,[wXMusBank]
    ld a,a                       ; padding no-op
    ld [rROMB0],a
    ld [wXCurBank],a
    jp XSnd_Update.check
.savePtr:
    ld a,h
    ld e,l
    ld hl,wXMusPtr
    ld [hl+],a
    ld [hl],e
.check:
    ld hl,wXMusTime              ; bc = clock
    ld a,[hl+]
    ld c,[hl]
    ld b,a
    ld hl,wXMusPtr
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    ld a,[hl+]                   ; event time hi - clock hi
    sub b
    jr c,XSnd_Update.late        ; already late: process
    jr nz,XSnd_Update.wait       ; future: wait
    ld a,[hl+]                   ; lo byte
    sub c
    jr c,XSnd_Update.dispatch
    jr z,XSnd_Update.dispatch
.wait:
    inc bc                       ; clock++ only on frames where nothing more is due
    ld hl,wXMusTime
    ld a,b
    ld [hl+],a
    ld [hl],c
    ld a,[wXSavedBank]
    ld a,a
    ld [rROMB0],a
    ld [wXCurBank],a
    ret
.late:
    inc hl
.dispatch:
    ld a,[hl+]                   ; d = command
    ld d,a
    and $F0
    cp $10
    jr nz,XSnd_Update.not1
    call XSnd_EvNote             ; $1c note
    jp XSnd_Update.savePtr
.not1:
    cp $20
    jr nz,XSnd_Update.not2
    call XSnd_EvCh3Off           ; $2x ch3 off
    jp XSnd_Update.savePtr
.not2:
    cp $30
    jr nz,XSnd_Update.not3
    call XSnd_EvCh3Vol           ; $3n ch3 volume
    jp XSnd_Update.savePtr
.not3:
    cp $40
    jr nz,XSnd_Update.not4
    call XSnd_EvWave             ; $4n wave
    jp XSnd_Update.savePtr
.not4:
    cp $50
    jr nz,XSnd_Update.end
    call XSnd_EvPitch            ; $5c pitch
    jp XSnd_Update.savePtr
.end:
    call XSnd_EvEnd              ; anything else ends the song
    ld a,[wXSavedBank]
    ld a,a
    ld [rROMB0],a
    ld [wXCurBank],a
    ret

XSnd_SfxTimers::
    ld a,[wXSfxTimer1]           ; called from VBlank after XSnd_Update
    cp $00
    jr z,XSnd_SfxTimers.ch2
    dec a
    ld [wXSfxTimer1],a
    cp $01                       ; reaching 1 retriggers the SFX (timer reloads)
    jr nz,XSnd_SfxTimers.ch2
    call XSnd_SfxCh1Start
.ch2:
    ld a,[wXSfxTimer2]
    cp $00
    jr z,XSnd_SfxTimers.ch4
    dec a
    ld [wXSfxTimer2],a
    cp $01
    jr nz,XSnd_SfxTimers.ch4
    call XSnd_SfxCh2Start
.ch4:
    ld a,[wXSfxTimer4]
    cp $00
    jr z,XSnd_SfxTimers.ch3
    dec a
    ld [wXSfxTimer4],a
    cp $01
    jr nz,XSnd_SfxTimers.ch3
    call XSnd_SfxCh4Start
.ch3:
    ld a,[wXSfxTimer3]
    cp $00
    jr z,XSnd_SfxTimers.done
    dec a
    ld [wXSfxTimer3],a
    cp $01
    jr nz,XSnd_SfxTimers.done
    ld a,[wXSndFlags]            ; not while the engine owns ch3
    bit 4,a
    jr nz,XSnd_SfxTimers.done
    call XSnd_SfxCh3Start
.done:
    ret

XSnd_EvNote:
    ld a,d
    and $0F
    cp $00
    jr nz,XSnd_EvNote.ch2
    ld bc,wXSndFlags
    ld a,[bc]
    bit 0,a
    jr z,XSnd_EvNote.ch1Play
    ldh a,[rNR52]                ; SFX still sounding? (NR52 status)
    bit 0,a
    jr z,XSnd_EvNote.ch1Free
    ld bc,$0003                  ; yes: skip the 3 data bytes
    add hl,bc
    ret
.ch1Free:
    ld a,[bc]                    ; SFX finished: give ch1 back to music
    res 0,a
    ld [bc],a
.ch1Play:
    ld a,$80                     ; sweep off
    ldh [rNR10],a
    ld a,[hl+]
    ldh [rNR12],a
    ld a,[hl+]
    ld d,a
    ld e,$04                     ; unused (leftover from length handling)
    srl e
    or $80                       ; NR11: duty from bit 6, bit 7 forced
    ldh [rNR11],a
    ld a,[hl+]
    ldh [rNR13],a
    ld a,d                       ; trigger, no length
    and $07
    or $80
    ldh [rNR14],a
    ret
.ch2:
    cp $01
    jr nz,XSnd_EvNote.ch3
    ld bc,wXSndFlags
    ld a,[bc]
    bit 1,a
    jr z,XSnd_EvNote.ch2Play
    ldh a,[rNR52]
    bit 1,a
    jr z,XSnd_EvNote.ch2Free
    ld bc,$0003
    add hl,bc
    ret
.ch2Free:
    ld a,[bc]
    res 1,a
    ld [bc],a
.ch2Play:
    ld a,[hl+]
    ldh [rNR22],a
    ld a,[hl+]
    ld d,a
    ld e,$04
    srl e
    or $80
    ldh [rNR21],a
    ld a,[hl+]
    ldh [rNR23],a
    ld a,d
    and $07
    or $80
    ldh [rNR24],a
    ret
.ch3:
    cp $02
    jr nz,XSnd_EvNote.ch4
    ld bc,wXSndFlags
    ld a,[bc]
    bit 2,a
    jr z,XSnd_EvNote.ch3Play
    ldh a,[rNR30]                ; NR30 DAC still on?
    bit 7,a
    jr z,XSnd_EvNote.ch3Free
    ld bc,$0002
    add hl,bc
    ret
.ch3Free:
    ld a,[bc]
    res 2,a
    ld [bc],a
    push hl                      ; restore the music wave
    ld hl,wXWaveSave
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    call XSnd_LoadWave
    pop hl
.ch3Play:
    ld a,$00                     ; NR34 = 0, NR30 = on
    ldh [rNR34],a
    ld a,$80
    ldh [rNR30],a
    ld a,[hl+]                   ; NR32 = high nibble
    ld d,a
    and $F0
    ldh [rNR32],a
    ld a,[hl+]
    ldh [rNR33],a
    ld a,d
    and $07
    or $80
    ldh [rNR34],a
    ret
.ch4:
    ld bc,wXSndFlags
    ld a,[bc]
    bit 3,a
    jr z,XSnd_EvNote.ch4Play
    ldh a,[rNR52]
    bit 3,a
    jr z,XSnd_EvNote.ch4Free
    ld bc,$0002                  ; BUG: the note is 1 byte, but 2 are skipped
    add hl,bc
    ret
.ch4Free:
    ld a,[bc]
    res 3,a
    ld [bc],a
.ch4Play:
    ld a,[hl+]                   ; d = volume (high nibble)
    ld b,a
    and $F0
    ld d,a
    ld a,b
    and $0F
    push hl
    ld hl,XNoiseTable            ; hl = XNoiseTable + 4 * index
    ld bc,$0004
.find:
    cp $00
    jr z,XSnd_EvNote.found
    add hl,bc
    dec a
    jp XSnd_EvNote.find
.found:
    ld a,[hl+]
    ldh [rNR41],a
    ld a,[hl+]                   ; NR42 = volume | envelope
    or d
    ldh [rNR42],a
    ld a,[hl+]
    ldh [rNR43],a
    ld a,[hl]
    ldh [rNR44],a
    pop hl
    ret

XSnd_EvCh3Off:
    ld a,[wXSndFlags]
    bit 2,a
    jr nz,XSnd_EvCh3Off.ret
    ld a,$00
    ldh [rNR30],a
.ret:
    ret

XSnd_EvCh3Vol:
    ld a,[wXSndFlags]
    bit 2,a
    jr nz,XSnd_EvCh3Vol.ret
    swap d                       ; NR32 = n << 4
    ld a,d
    and $F0
    ldh [rNR32],a
.ret:
    ret

XSnd_EvWave:
    ld a,d                       ; BUG: stores the index in the high byte of the
    and $0F
    ld d,a
    ld [wXWaveSave],a            ; saved wave pointer
    ld a,[wXSndFlags]
    bit 2,a
    jr z,XSnd_EvWave.load
    ret
.load:
    push hl
    ld hl,XWaveTable             ; hl = XWaveTable + 16 * n
    ld bc,$0010
    ld a,d
.find:
    cp $00
    jr z,XSnd_EvWave.found
    add hl,bc
    dec a
    jp XSnd_EvWave.find
.found:
    call XSnd_LoadWave
    pop hl
    ret

XSnd_EvPitch:
    ld a,d
    and $0F
    cp $00
    jr nz,XSnd_EvPitch.notCh1
    ld a,[wXSndFlags]            ; ch1 has no NR52 check here
    bit 0,a
    jr z,XSnd_EvPitch.ch1
    ld bc,$0002
    add hl,bc
    ret
.ch1:
    ld a,[hl+]
    ldh [rNR13],a
    ld a,[hl+]
    and $07                      ; no trigger
    ldh [rNR14],a
    ret
.notCh1:
    cp $01
    jr nz,XSnd_EvPitch.ch3
    ld a,[wXSndFlags]
    bit 1,a
    jr z,XSnd_EvPitch.ch2
    ld bc,$0002
    add hl,bc
    ret
.ch2:
    ld a,[hl+]
    ldh [rNR23],a
    ld a,[hl+]
    and $07
    ldh [rNR24],a
    ret
.ch3:
    ld a,[wXSndFlags]
    bit 2,a
    jr z,XSnd_EvPitch.ch3Write
    ld bc,$0002
    add hl,bc
    ret
.ch3Write:
    ld a,[hl+]
    ldh [rNR33],a
    ld a,[hl+]
    and $07
    ldh [rNR34],a
    ret

XSnd_EvEnd:
    call XSnd_StopMusic
    ld b,BANK(XSong_Title)       ; queue XSong_Title, then start it at once
    ld de,XSong_Title
    call XSnd_QueueSong
    ld a,[wXSndFlags]            ; always set: just queued
    bit 7,a
    jr z,XSnd_EvEnd.ret
    res 7,a
    ld [wXSndFlags],a
    ld hl,wXQueuedPtr
    ld a,[hl+]
    ld d,a
    ld a,[hl+]
    ld e,a
    ld a,[hl+]
    call XSnd_PlaySong
.ret:
    ret

XSnd_SfxCh2Start::
    ld de,rNR21
    ld hl,wXSndFlags
    ld a,[hl]
    set 1,a
    ld [hl],a
    ld hl,wXSfxPtr2              ; wXSfxPtr2 is never set by the game
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    ld a,[hl+]
    ld [wXSfxTimer2],a
    jp XSnd_SfxCopy4

XSnd_PlaySfxCh3::
    ld a,[wXSndFlags]            ; hl = wave for the SFX
    bit 4,a
    jr z,XSnd_PlaySfxCh3.notEngine
    ret
.notEngine:
    bit 2,a
    jr nz,XSnd_PlaySfxCh3.load
    ld a,[wXWaveCur]             ; save the music wave
    ld [wXWaveSave],a
    ld a,[wXWaveCur+1]
    ld [wXWaveSave+1],a
.load:
    call XSnd_LoadWave

XSnd_SfxCh3Start::
    ld de,rNR30
    ld hl,wXSndFlags
    ld a,[hl]
    set 2,a
    ld [hl],a
    ld hl,wXSfxPtr3
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    ld a,$00                     ; DAC off, NR34 = 0
    ldh [rNR30],a
    ldh [rNR34],a
    ld a,[hl+]
    ld [wXSfxTimer3],a
    jp XSnd_SfxCopy5

XSnd_SfxCh4Start::
    ld de,rNR41
    ld hl,wXSndFlags
    ld a,[hl]
    set 3,a
    ld [hl],a
    ld hl,wXSfxPtr4
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    ld a,[hl+]
    ld [wXSfxTimer4],a
    jp XSnd_SfxCopy4

XSnd_SfxCh1Start::
    ld de,rNR10
    ld hl,wXSndFlags
    ld a,[hl]
    set 0,a
    ld [hl],a
    ld hl,wXSfxPtr1
    ld a,[hl+]
    ld l,[hl]
    ld h,a
    ld a,[hl+]
    ld [wXSfxTimer1],a

XSnd_SfxCopy5:
    ld a,[hl+]
    ld [de],a
    inc de

XSnd_SfxCopy4:
    ld a,[hl+]
    ld [de],a
    inc de
    ld a,[hl+]
    ld [de],a
    inc de
    ld a,[hl+]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a
    ret

XSnd_SfxCh1Stop::
    ld a,$00
    ld [wXSfxTimer1],a
    ld hl,wXSndFlags
    ld a,[hl]
    res 0,a
    ld [hl],a
    ret

XSnd_SfxCh2Stop::
    ld a,$00
    ldh [rNR22],a
    ld a,$00
    ld [wXSfxTimer2],a
    ld hl,wXSndFlags
    ld a,[hl]
    res 1,a
    ld [hl],a
    ret

XSnd_SfxCh3Stop::
    ld a,$00
    ldh [rNR30],a
    ld [wXSfxTimer3],a
    ld hl,wXSndFlags
    ld a,[hl]
    res 2,a
    ld [hl],a
    ret

XSnd_SfxCh4Stop::
    ld a,$00
    ldh [rNR42],a
    ld a,$00
    ld [wXSfxTimer4],a
    ld hl,wXSndFlags
    ld a,[hl]
    res 3,a
    ld [hl],a
    ret

XSnd_EngineUpdate::
    ld a,[wXSndFlags]            ; called from the timer interrupt
    bit 4,a
    jr nz,XSnd_EngineUpdate.on
    ret
.on:
    ld a,[wXEngineRpmLast]
    ld b,a
    ld a,[wXEngineRpm]
    ld [wXEngineRpmLast],a
    cp b
    jr nz,XSnd_EngineUpdate.changed
    ret
.changed:
    ld b,a
    ld hl,$0000                  ; rpm 0: period 0
    cp $00
    jr z,XSnd_EngineUpdate.write
    ld de,$0020                  ; hl = 32 * (rpm & $0F)
    and $0F
.mul:
    cp $00
    jr z,XSnd_EngineUpdate.gear
    add hl,de
    dec a
    jp XSnd_EngineUpdate.mul
.gear:
    ld a,b
    and $F0
    ld bc,XEngineGearBase        ; de = XEngineGearBase[rpm >> 4] (no bound check)
.find:
    cp $00
    jr z,XSnd_EngineUpdate.found
    inc bc
    inc bc
    sub $10
    jp XSnd_EngineUpdate.find
.found:
    ld a,[bc]
    ld d,a
    inc bc
    ld a,[bc]
    ld e,a
    add hl,de
.write:
    ld a,l                       ; retrigger ch3 with the new period
    ldh [rNR33],a
    ld a,h
    or $80
    ldh [rNR34],a
    ret

XSnd_EngineOn::
    ld a,[wXSndFlags]
    bit 4,a
    jr nz,XSnd_EngineOn.ret
    push hl
    ld hl,XSfx_Engine            ; ch3 SFX = XSfx_Engine with XWave_Engine
    ld a,h
    ld [wXSfxPtr3],a
    ld a,l
    ld [wXSfxPtr3+1],a
    ld hl,XWave_Engine
    call XSnd_PlaySfxCh3
    pop hl
    ld a,[wXSndFlags]
    set 4,a
    ld [wXSndFlags],a
.ret:
    ret

XSnd_EngineOff::
    ld a,[wXSndFlags]
    bit 4,a
    jr z,XSnd_EngineOff.ret
    res 4,a
    ld [wXSndFlags],a
    call XSnd_SfxCh3Stop         ; the music wave is not restored
.ret:
    ret

; engine period base per rpm high nibble, big-endian
XEngineGearBase:
    bigw $0200, $01A0, $0150, $0100

; SFX records. The game sets wXSfxPtrN and calls XSnd_SfxChNStart.
XSfx_Engine:
    sfx3 $00, $80, $74, $20, $00, $80   ; engine voice: XSnd_EngineOn
XSfx4_386B:
